-- Dashboard and reporting queries with aggregation, subqueries and CTEs
SELECT status, COUNT(*) AS n, SUM(total) AS revenue FROM orders GROUP BY status HAVING SUM(total) > 1000 ORDER BY revenue DESC;
SELECT YEAR(created_at) AS y, MONTH(created_at) AS m, SUM(total) FROM orders GROUP BY YEAR(created_at), MONTH(created_at) WITH ROLLUP;
SELECT category_id, COUNT(DISTINCT user_id) AS buyers FROM order_items i JOIN orders o ON o.id = i.order_id GROUP BY category_id;
SELECT GROUP_CONCAT(name ORDER BY name SEPARATOR ', ') FROM tags;
SELECT user_id, GROUP_CONCAT(DISTINCT status) FROM orders GROUP BY user_id;
SELECT d.dt, COALESCE(s.cnt, 0) FROM calendar d LEFT JOIN (SELECT DATE(created_at) AS dt, COUNT(*) AS cnt FROM orders GROUP BY DATE(created_at)) s ON s.dt = d.dt;
WITH monthly AS (SELECT DATE_FORMAT(created_at, '%Y-%m-01') AS month, SUM(total) AS rev FROM orders GROUP BY 1) SELECT month, rev FROM monthly ORDER BY month;
WITH a AS (SELECT user_id, SUM(total) AS t FROM orders GROUP BY user_id), b AS (SELECT user_id, COUNT(*) AS c FROM sessions GROUP BY user_id), c AS (SELECT a.user_id, a.t, b.c FROM a JOIN b USING (user_id)) SELECT * FROM c WHERE t > 500;
SELECT u.id, (SELECT COUNT(*) FROM orders o WHERE o.user_id = u.id) AS order_count FROM users u;
SELECT * FROM (SELECT user_id, MAX(total) AS mx FROM orders GROUP BY user_id) AS t WHERE mx > 100;
SELECT a.id FROM a JOIN b ON a.id = b.a_id JOIN c ON c.b_id = b.id JOIN d ON d.c_id = c.id LEFT JOIN e ON e.d_id = d.id LEFT JOIN f ON f.e_id = e.id WHERE f.id IS NULL;
SELECT t1.id FROM t1 NATURAL JOIN t2;
SELECT t1.id FROM t1 CROSS JOIN t2 WHERE t1.x = t2.y;
SELECT t1.id FROM t1 STRAIGHT_JOIN t2 ON t1.id = t2.id;
SELECT t1.id FROM t1 RIGHT JOIN t2 ON t1.id = t2.id;
SELECT * FROM t1 UNION SELECT * FROM t2 UNION ALL SELECT * FROM t3 ORDER BY 1 LIMIT 10;
(SELECT id FROM t1 ORDER BY id LIMIT 5) UNION ALL (SELECT id FROM t2 ORDER BY id LIMIT 5);
SELECT SQL_CALC_FOUND_ROWS id FROM users LIMIT 10;
SELECT FOUND_ROWS();
SELECT * FROM t1 USE INDEX (idx_a) WHERE a = 1;
SELECT * FROM t1 FORCE INDEX (idx_a, idx_b) WHERE a = 1 OR b = 2;
SELECT * FROM t1 IGNORE INDEX FOR ORDER BY (idx_a) ORDER BY a;
SELECT AVG(total), STDDEV(total), MIN(total), MAX(total) FROM orders;
SELECT IF(total > 100, 'hi', 'lo') AS tier, COUNT(*) FROM orders GROUP BY tier;
SELECT DATEDIFF(NOW(), created_at) AS age_days, TIMESTAMPDIFF(HOUR, created_at, NOW()) FROM users;
SELECT DATE_ADD(NOW(), INTERVAL 7 DAY), DATE_SUB(CURDATE(), INTERVAL 1 MONTH);
SELECT * FROM orders WHERE created_at >= NOW() - INTERVAL 30 DAY;
SELECT id, total INTO @id, @total FROM orders WHERE id = 1;
SELECT CAST(total AS DECIMAL(10, 2)), CAST(id AS CHAR), CONVERT(name, CHAR(50)) FROM orders;
SELECT 1 + 2 * 3, (1 + 2) * 3, 10 DIV 3, 10 MOD 3, 10 % 3, 2 << 3, 5 & 3, 5 | 3, 5 ^ 3, ~5;
SELECT * FROM users WHERE name REGEXP '^A' AND email NOT REGEXP 'test';
SELECT * FROM users WHERE a <=> NULL AND b IS NOT NULL AND NOT c;
SELECT 'a' || 'b';
SELECT * FROM t WHERE x = 1 XOR y = 2;
SHOW TABLES;
SHOW COLUMNS FROM users;
SHOW CREATE TABLE users;
SHOW INDEX FROM orders;
SHOW VARIABLES LIKE 'max_connections';
SHOW FULL PROCESSLIST;
SHOW GRANTS FOR 'app'@'localhost';
SHOW STATUS LIKE 'Threads%';
DESCRIBE users;
EXPLAIN SELECT * FROM users WHERE id = 1;
EXPLAIN FORMAT=JSON SELECT * FROM orders WHERE user_id = 1;
